import { K8sProvider, K8sProviderError } from './K8sProvider';
import * as k8s from '@kubernetes/client-node';
import { InfraSpec, K8sResource, ResourceType } from './types/infra_spec';
import { Logger } from '../../utils/Logger';

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

jest.mock('@kubernetes/client-node');
jest.mock('../../utils/Logger');

const MockedKubeConfig = k8s.KubeConfig as jest.MockedClass<typeof k8s.KubeConfig>;
const MockedCoreV1Api = k8s.CoreV1Api as jest.MockedClass<typeof k8s.CoreV1Api>;
const MockedAppsV1Api = k8s.AppsV1Api as jest.MockedClass<typeof k8s.AppsV1Api>;
const MockedNetworkingV1Api = k8s.NetworkingV1Api as jest.MockedClass<typeof k8s.NetworkingV1Api>;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function createMockSpec(overrides?: Partial<InfraSpec>): InfraSpec {
  return {
    version: 'v1',
    metadata: {
      name: 'test-deployment',
      namespace: 'test-ns',
      labels: { app: 'test' },
    },
    resources: [],
    ...overrides,
  };
}

function createMockResource(overrides?: Partial<K8sResource>): K8sResource {
  return {
    type: ResourceType.Deployment,
    name: 'test-deployment',
    spec: {
      replicas: 2,
      containers: [
        {
          name: 'app',
          image: 'nginx:1.21',
          ports: [{ containerPort: 80 }],
        },
      ],
    },
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Suite
